// src/MapDisplay.js
import React from 'react';
import "./App.css";
import { GoogleMap, useJsApiLoader, Marker, Polyline } from '@react-google-maps/api';

const mapContainerStyle = {
  width: '100%',
  height: '400px'
};

export default function MapDisplay({ routeData, defaultCenter, zoom = 13 }) {
  const { isLoaded, loadError } = useJsApiLoader({
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY,
  });

  if (loadError)  return <div style={{ padding: '1rem', color: 'red' }}>Error loading map</div>;
  if (!isLoaded) return <div style={{ padding: '1rem' }}>Loading map…</div>;

  // Turn [lat, lng] arrays into {lat, lng} objects
  const path = (routeData || []).map(([lat, lng]) => ({ lat, lng }));

  return (
    <GoogleMap
      mapContainerStyle={mapContainerStyle}
      center={{ lat: defaultCenter[0], lng: defaultCenter[1] }}
      zoom={zoom}
      options={{
        streetViewControl: false,
        mapTypeControl: false,
        fullscreenControl: false,
      }}
    >
      {path.map((pos, i) => (
        <Marker
          key={i}
          position={pos}
          label={{
            text: String(i + 1),
            color: '#fff',
            fontSize: '12px',
            fontWeight: 'bold',
          }}
          icon={{
            path: window.google.maps.SymbolPath.CIRCLE,
            fillColor: '#4285F4',
            fillOpacity: 1,
            strokeOpacity: 0,
            scale: 16,
          }}
        />
      ))}

      {path.length > 1 && (
        <Polyline
          path={path}
          options={{
            strokeColor: '#4285F4',
            strokeOpacity: 0.8,
            strokeWeight: 4,
            clickable: false,
            editable: false,
            geodesic: true,
          }}
        />
      )}
    </GoogleMap>
  );
}



